// Merge SerpAPI and Tavily results into a single context string
const serpData = $('SerpAPI — Busca Skincare').item.json;
const tavilyData = $input.first().json;

let contextParts = [];

// Extract SerpAPI organic results
if (serpData.organic_results && Array.isArray(serpData.organic_results)) {
  const serpSnippets = serpData.organic_results
    .slice(0, 10)
    .map((r, i) => `[Fonte ${i + 1}] ${r.title || ''}:\n${r.snippet || ''}\nURL: ${r.link || ''}`)
    .join('\n\n');
  contextParts.push('=== Resultados SerpAPI ===\n' + serpSnippets);
}

// Extract Tavily results
if (tavilyData.results && Array.isArray(tavilyData.results)) {
  const tavilySnippets = tavilyData.results
    .slice(0, 5)
    .map((r, i) => `[Tavily ${i + 1}] ${r.title || ''}:\n${r.content || ''}\nURL: ${r.url || ''}`)
    .join('\n\n');
  contextParts.push('=== Resultados Tavily ===\n' + tavilySnippets);
}

const contexto_pesquisa = contextParts.join('\n\n');
const tema_semana = $('Set Tema da Semana').item.json.tema_semana;
const clima_semana = $('Set Tema da Semana').item.json.clima_semana;

return [{ json: { contexto_pesquisa, tema_semana, clima_semana } }];

// Extract text content from Claude API response
const response = $input.first().json;

let html_content = '';

if (response.content && Array.isArray(response.content) && response.content.length > 0) {
  html_content = response.content[0].text || '';
} else {
  throw new Error('Claude API did not return expected content structure: ' + JSON.stringify(response));
}

// Wrap with minimal styling for PDF
const html_wrapped = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: 'Georgia', serif; color: #3a2a1e; margin: 40px; line-height: 1.7; }
    h1 { color: #8b5e3c; font-size: 2em; border-bottom: 2px solid #e8c9a0; padding-bottom: 10px; }
    h2 { color: #8b5e3c; font-size: 1.5em; margin-top: 2em; }
    h3 { color: #a0714f; font-size: 1.2em; }
    p { margin: 0.8em 0; }
    ul { margin: 0.5em 0 1em 1.5em; }
    li { margin: 0.3em 0; }
  </style>
</head>
<body>
  <h1>Refúgio da Pele — PDF Semanal</h1>
  ${html_content}
</body>
</html>`;

return [{ json: { html_content: html_wrapped } }];
